import { Component, forwardRef, ElementRef, ViewChild } from '@angular/core';

@Component({
  selector: 'app-child',
  template: '<button>Click me</button>'
})
export class ChildComponent {
  constructor(public elementRef: ElementRef) {}
}

@Component({
  selector: 'app-parent',
  template: `
    <app-child #childRef></app-child>
    <button (click)="logChildElement()">Log Child DOM</button>
  `
})
export class ParentComponent {
  @ViewChild('childRef', { read: ElementRef }) childElement!: ElementRef;

  logChildElement() {
    console.log(this.childElement.nativeElement);
  }
}
